import{_ as t,o as r,c as l,a2 as e}from"./chunks/framework.B2QVIpOM.js";const k=JSON.parse('{"title":"福建中学 · 2018–19年度 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"fukien","school_zh":"福建中学","school_en":"Fukien Secondary School","grade":"s1","year":"2018-19","year_label":"2018–19年度","type":"interview","title":"福建中学 · 2018–19年度 · 中一 · 面试","anonymous":true,"source_ids":["M011-2018-19"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/fukien/s1/2018-19-interview.md","filePath":"reports/fukien/s1/2018-19-interview.md"}'),s={name:"reports/fukien/s1/2018-19-interview.md"};function n(p,o,i,a,g,u){return r(),l("div",null,[...o[0]||(o[0]=[e('<h1 id="福建中学-·-2018–19年度-·-中一-·-面试" tabindex="-1">福建中学 · 2018–19年度 · 中一 · 面试 <a class="header-anchor" href="#福建中学-·-2018–19年度-·-中一-·-面试" aria-label="Permalink to &quot;福建中学 · 2018–19年度 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/fukien">← 返回福建中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-m011-2018-19" tabindex="-1">资料来源：【其它机构】升中面试经验汇总_18-21.pdf <a class="header-anchor" href="#record-m011-2018-19" aria-label="Permalink to &quot;资料来源：【其它机构】升中面试经验汇总_18-21.pdf {#record-m011-2018-19}&quot;">​</a></h2><p><strong>资料类型：</strong> 面试反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>問卷時長</strong></p><p>學生填寫問卷，限時20分鐘。</p></blockquote><blockquote><p><strong>资料填写：</strong> 中文</p><p><strong>基本資料與學校生活</strong></p><ul><li>填寫中、英文姓名、出生地點、出生日期及中文地址。</li><li>回答是否享受學校生活，並說明原因。</li></ul></blockquote><blockquote><p><strong>资料填写：</strong> 英语</p><p><strong>科目偏好</strong></p><ul><li>說明最喜歡的科目及原因。</li><li>說明最不喜歡的科目及原因。</li></ul></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗讀與理解</strong></p><ul><li>朗讀一篇文章，回答3條相關問題。</li><li>朗讀一首詩，回答1條相關問題。</li></ul><p><strong>問卷追問與入學設想</strong></p><ul><li>就問卷的英文部分追問最喜歡及最不喜歡的科目，並說明原因。</li><li>回答若獲取錄並入讀，可以做些甚麼。</li></ul></blockquote><blockquote><p><strong>语文：</strong> 普通话</p><p><strong>自我介紹</strong></p><p>考生作自我介紹。</p></blockquote><blockquote><p><strong>语文：</strong> 粤语</p><p><strong>個人問答</strong></p><ul><li>回答哪個人或哪件事最應影響自己。</li><li>說明最喜歡及最不喜歡的科目，並解釋原因。</li></ul><p><strong>詞語造句</strong></p><p>使用「商場、聖誕節、熱鬧」三個指定詞語造句。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>電腦限時測試</strong></p><p>以電腦完成10道奧數選擇題，限時10分鐘。</p><p><strong>特殊運算例題</strong></p><p>題目以外星人使用的「@」代表一種運算（例如加、減、乘、除），給出 x@y = x+yxX+y，要求求出 (2@3) 的結果。原式運算符號仍不清楚，不能据此還原完整算式。另一題在原資料中僅留有「另一條」字樣，未提供題幹。</p></blockquote><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>小組合作砌模型</strong></p><p>每組4至5人，兩位教師在旁觀察評分。考生須在8分鐘內按提供的說明書合作砌模型；零件並不齊全，需要共同設法完成。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>情境處理</strong></p><p>第二輪設有情境題：考生觀看一幅圖片，說明會如何處理圖中情況。</p></blockquote><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>交通事故情境</strong></p><p>材料舉例：早上地鐵發生事故，等候很久仍沒有列車，考生應說明如何上學及會採取甚麼行動。教師會根據回答改變假設，繼續追問在新情況下會怎樣處理。</p></blockquote><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>副校長面談：自我介紹與選校</strong></p><ul><li>考生先作自我介紹。</li><li>說明報考本校的原因，以及學校哪些地方吸引自己。</li></ul><p><strong>成績與學習</strong></p><ul><li>教師邊查看成績及Portfolio邊提問：強項科目如何發展？弱項科目有甚麼具體改善方法？</li><li>說明成績在原校屬高、中或低的位置，並評價自己的表現。</li><li>說明自身弱點及改善計畫。</li></ul><p><strong>才能與經歷追問</strong></p><ul><li>詳細討論Portfolio，說明如何發揮及發展才能。繪畫例題包括：為甚麼喜歡畫畫、幾歲開始、為何喜歡多色彩繪畫、屬於哪種畫風，以及未來如何發展。</li><li>教師因考生自稱開朗、喜歡多色彩而追問：最近一次哭是甚麼時候？為甚麼？</li></ul><p><strong>學校適應與語言</strong></p><ul><li>教師指出本校與原校差異很大，詢問考生是否了解，是否認識本校學生。</li><li>詢問原校課堂及同學間是否使用英語交談。</li><li>教師提及校內內地學生中文及數學較強，詢問考生是否有信心。</li><li>詢問對內地人的看法、如何與其相處、普通話程度及在哪裏學習，以及是否經常到內地。</li></ul><p><strong>家庭與上學安排</strong></p><ul><li>詢問有沒有兄弟姊妹、平日由誰照顧；考生自稱獨立時，須舉出具體例子。</li><li>教師提及兩校交通均不方便，詢問當日如何到校、獲錄取後怎樣上學，以及是否自行查過路線。</li></ul><p><strong>升學選擇與未來規劃</strong></p><ul><li>是否報考其他學校？若同時獲錄取，會如何選擇？</li><li>將來想從事甚麼職業？教師指出該目標難以實現時，須說明實現方法及其他職業選擇。</li><li>若可以向教師提一個問題，會問甚麼？</li></ul></blockquote>',20)])])}const b=t(s,[["render",n]]);export{k as __pageData,b as default};
